CREATE POLICY "tenant and staff can select orders" ON "app"."orders" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((select private.can_view_org("app"."orders"."organization_id")));
CREATE POLICY "staff can insert orders" ON "app"."orders" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((select private.is_hoc_staff()));
CREATE POLICY "staff can update orders" ON "app"."orders" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((select private.is_hoc_staff())) WITH CHECK ((select private.is_hoc_staff()));
CREATE POLICY "owner can accept order terms while deposit is due" ON "app"."orders" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((select private.has_org_role("app"."orders"."organization_id", array['owner']::text[])) and "app"."orders"."status" = 'deposit_pending') WITH CHECK ((select private.has_org_role("app"."orders"."organization_id", array['owner']::text[])) and "app"."orders"."status" = 'deposit_pending');
CREATE POLICY "tenant and staff can select payments" ON "app"."payments" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((select private.can_view_org("app"."payments"."organization_id")));
CREATE POLICY "owner or staff can insert payment attempts" ON "app"."payments" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((select private.is_hoc_staff()) or (select private.has_org_role("app"."payments"."organization_id", array['owner']::text[])));
